     1	import java.util.List;
     2	import java.util.Map;
     3	import java.util.Set;
     4	import java.util.stream.Collectors;
     5	
     6	/**
     7	 * The MHPCO pricing policy for components: 25 G base premium each, with a
     8	 * building block of exactly 3 alike components offered at 60 G.
     9	 */
    10	public final class ComponentPricing {
    11	
    12	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
    13	
    14	    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;
    15	
    16	    private static final int COMPONENT_INSURANCE_VALUE_IN_G = 250;
    17	
    18	    private static final int COMPONENTS_PER_BLOCK = 3;
    19	
    20	    private static final int BLOCK_BASE_PREMIUM_IN_G = 60;
    21	
    22	    private ComponentPricing() {
    23	    }
    24	
    25	    public static boolean isComponent(String itemType) {
    26	        return COMPONENT_TYPES.contains(itemType);
    27	    }
    28	
    29	    /**
    30	     * The base premium for every component in a policy: components are grouped
    31	     * into sets of alike components, and each set is priced on its own.
    32	     */
    33	    public static int componentsBasePremium(List<Item> items) {
    34	        Map<String, Long> alikeCounts = items.stream()
    35	                .filter(item -> isComponent(item.type()))
    36	                .collect(Collectors.groupingBy(ComponentPricing::alikeGroup, Collectors.counting()));
    37	        return alikeCounts.values().stream()
    38	                .mapToInt(count -> alikeComponentsBasePremium(count.intValue()))
    39	                .sum();
    40	    }
    41	
    42	    /**
    43	     * Components are alike when they are of the same item type: a rune and a
    44	     * moonstone are never alike, however rune-y or gemstone-y they look. This
    45	     * is the one place the MHPCO's reading of "alike" is decided.
    46	     */
    47	    private static String alikeGroup(Item item) {
    48	        return item.type();
    49	    }
    50	
    51	    private static int alikeComponentsBasePremium(int count) {
    52	        if (formsABlock(count)) {
    53	            return BLOCK_BASE_PREMIUM_IN_G;
    54	        }
    55	        return count * COMPONENT_BASE_PREMIUM_IN_G;
    56	    }
    57	
    58	    /**
    59	     * The MHPCO offers the block only for exactly 3 alike components: 4 alike
    60	     * components are not a block plus a spare, and 7 are not two blocks plus a
    61	     * spare -- each of those is charged at the full per-component premium.
    62	     */
    63	    private static boolean formsABlock(int alikeCount) {
    64	        return alikeCount == COMPONENTS_PER_BLOCK;
    65	    }
    66	
    67	    /**
    68	     * Every component is insured at 250 G, whatever the MHPCO charges for the
    69	     * set it belongs to: the block offer reduces the premium, not the value.
    70	     */
    71	    public static int componentInsuranceValue(Item item) {
    72	        return COMPONENT_INSURANCE_VALUE_IN_G;
    73	    }
    74	}
