import java.util.List;

/**
 * A policy the MHPCO has issued over a list of insured items. The insurance
 * sum is what the covered items are insured for; the MHPCO pays out at most
 * twice that sum over the life of the policy.
 */
public final class Policy {

    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

    private final List<Item> insuredItems;

    public Policy(List<Item> insuredItems) {
        this.insuredItems = List.copyOf(insuredItems);
    }

    public int insuranceSum() {
        return insuredItems.stream()
                .mapToInt(InsurableItems::insuranceValueOf)
                .sum();
    }

    /**
     * The most the MHPCO will pay out over the life of this policy: twice the
     * insurance sum. No claim has yet been made against a policy, so this is
     * the whole cap; what remains of it after claims is a claim's concern.
     */
    public int cap() {
        return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum();
    }
}
